import { PhoneCall } from 'lucide-react';
import Link from 'next/link';

export default function Consultation() {
  return (
    <section className="py-16 bg-secondary">
      <div className="container mx-auto px-4 flex flex-col items-center">
        <div className="flex items-center gap-3 mb-6">
          <PhoneCall className="text-accent" size={40} />
          <h2 className="font-headline text-3xl md:text-4xl font-bold text-foreground">Zapraszamy do konsultacji i wyceny</h2>
        </div>
        <p className="text-lg md:text-xl text-center max-w-2xl mb-6 text-muted-foreground">
          Skontaktuj się z nami, aby omówić swój wymarzony projekt. Odpowiemy na wszystkie pytania i przygotujemy indywidualną wycenę.
        </p>
        <Link href="https://www.epir-art.com/konsultacja" target="_blank" rel="noopener noreferrer">
          <span className="inline-block bg-accent text-accent-foreground font-semibold px-8 py-3 rounded-lg shadow-lg hover:bg-accent/90 transition">Zamów konsultację</span>
        </Link>
      </div>
    </section>
  );
}
