import { Gem, Facebook, Instagram, Twitter } from 'lucide-react';
import Link from 'next/link';

export default function Footer() {
  return (
    <footer className="bg-primary text-primary-foreground">
      <div className="container py-12 px-4 md:px-6">
        <div className="flex flex-col md:flex-row justify-between items-center text-center md:text-left gap-8">
          <div className="flex items-center space-x-2">
            <Gem className="h-6 w-6" />
            <span className="font-bold font-headline text-lg">EPIR Art Jewellery</span>
          </div>
          <div>
            <p>Wrocław, Polska</p>
            <p className="text-sm text-primary-foreground/70">&copy; {new Date().getFullYear()} EPIR Art Jewellery. Wszelkie prawa zastrzeżone.</p>
          </div>
          <div className="flex space-x-4">
            <Link href="#" className="hover:opacity-80 transition-opacity" aria-label="Facebook"><Facebook /></Link>
            <Link href="#" className="hover:opacity-80 transition-opacity" aria-label="Instagram"><Instagram /></Link>
            <Link href="#" className="hover:opacity-80 transition-opacity" aria-label="Twitter"><Twitter /></Link>
          </div>
        </div>
      </div>
    </footer>
  );
}