'use server';

import { chatBotPodajeLinkDoKonsultacji } from '@/ai/flows/chatbot-podaje-link-do-konsultacji';

export async function getChatbotResponse(userQuery: string): Promise<string> {
  if (!userQuery || userQuery.trim() === '') {
    return "Wiadomość nie może być pusta.";
  }
  
  try {
    const result = await chatBotPodajeLinkDoKonsultacji({ userQuery });
    return result.response;
  } catch (error) {
    console.error('Błąd wywołania AI:', error);
    return 'Przepraszamy, wystąpił błąd. Spróbuj ponownie później.';
  }
}