import { Gem } from 'lucide-react';

export default function CustomOrders() {
  return (
    <section className="py-16 bg-background">
      <div className="container mx-auto px-4 flex flex-col items-center">
        <div className="flex items-center gap-3 mb-6">
          <Gem className="text-accent" size={40} />
          <h2 className="font-headline text-3xl md:text-4xl font-bold text-foreground">Zamówienia indywidualne</h2>
        </div>
        <p className="text-lg md:text-xl text-center max-w-2xl mb-6 text-muted-foreground">
          Marzysz o wyjątkowej biżuterii? Stworzymy dla Ciebie pierścionek zaręczynowy lub inny projekt według Twojego pomysłu. Każdy detal konsultujemy i dopracowujemy wspólnie z Tobą.
        </p>
      </div>
    </section>
  );
}
